// Native recruiter operations, original reward Lua and original running scans.
// No UI request starts or advances a contraband scan.
class SwgxrGcw {
 using Json=JSONSerializationType;
 static std::string str(const String& s){return s.toCharArray();}
 static uint64 now(){return std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count();}
 static const Json& catalog(){static const Json data=[](){for(const char* path:std::initializer_list<const char*>{std::getenv("SWGXR_GCW_CATALOG_PATH"),"../../../../runtime/assets/gcw/catalog.json","runtime/assets/gcw/catalog.json"}){if(!path)continue;std::ifstream file(path);if(!file)continue;try{Json row;file>>row;if(row.value("schema",0)==1 && row.contains("rewards") && row["rewards"].is_array() && row["rewards"].size()<=256)return row;}catch(...) {}}Logger::console.warning("SWGXR GCW reward catalog unavailable; prepare runtime/assets/gcw/catalog.json.");return Json{{"rewards",Json::array()}};}();return data;}
 static int cost(CreatureObject* c,const std::string& f,const std::string& key){auto lua=DirectorManager::instance()->getLuaInstance();LuaFunction fn(lua->getLuaState(),"recruiterScreenplay","swgxrCost",1);fn<<c;fn<<f.c_str();fn<<key.c_str();fn.callFunction();bool valid=lua_isnumber(lua->getLuaState(),-1);int value=valid?lua_tointeger(lua->getLuaState(),-1):-1;lua_pop(lua->getLuaState(),1);return value;}
 static bool jedi(CreatureObject* c){return c->hasSkill("force_rank_light_novice") || c->hasSkill("force_rank_dark_novice");}
 static int standing(CreatureObject* c,const std::string& f){return c->getPlayerObject()->getFactionStanding(String(f.c_str()));}
public:
 static std::string faction(CreatureObject* c){return c->isImperial()?"imperial":c->isRebel()?"rebel":"neutral";}
 static bool recruiter(SceneObject* o){if(!o || !o->isAiAgent())return false;auto npc=o->asAiAgent();auto crc=npc->getConvoTemplateCRC();return (npc->isImperial() && crc==String("imperialRecruiterConvoTemplate").hashCode()) || (npc->isRebel() && crc==String("rebelRecruiterConvoTemplate").hashCode());}
 static void validate(CreatureObject* c,SceneObject* npc,float range=5){if(!recruiter(npc) || npc->getZone()!=c->getZone() || npc->getParentID()!=c->getParentID() || !npc->isInRange(c,range) || npc->asAiAgent()->isDead() || npc->asAiAgent()->isIncapacitated() || !CollisionManager::checkLineOfSight(npc,c))throw std::runtime_error("recruiter_unavailable_cell_distance_or_sight");}
 static bool canToggle(CreatureObject* c,SceneObject* npc){return recruiter(npc) && faction(c)==faction(npc->asCreatureObject()) && c->getFutureFactionStatus()<0 && c->getFactionStatus()<=1 && !jedi(c) && !c->isDead() && !c->isIncapacitated() && !c->isInCombat();}
 static Json scan(CreatureObject* c){auto session=c->getActiveSession(SessionFacadeType::CONTRABANDSCAN).castTo<ContrabandScanSession*>();auto ghost=c->getPlayerObject();Json out={{"active",session!=nullptr},{"id",""},{"phase",-1},{"phase_name","idle"},{"answer_pending",false},{"answer_given",false},{"fine",0},{"contraband_count",0},{"crackdown_tef",{{"imperial",ghost->hasCrackdownTefTowards(Factions::FACTIONIMPERIAL)},{"rebel",ghost->hasCrackdownTefTowards(Factions::FACTIONREBEL)}}}};if(c->getZone() && c->getZone()->getGCWManager() && c->getInventory())out["contraband_count"]=c->getZone()->getGCWManager()->countContrabandItems(c);if(!session)return out;int phase=session->getSwgxrPhase();const char* names[]={"checking","initiating","return_to_scanner","mind_trick","scanner_considers","scanner_replies","jedi_check","faction_check","scanning","fine","finished"};auto scanner=session->getSwgxrScanner();out["id"]=std::to_string(session->getSwgxrScanID());out["phase"]=phase;out["phase_name"]=phase>=0 && phase<=10?names[phase]:"unknown";out["scanner_id"]=scanner?std::to_string(scanner->getObjectID()):"0";out["fine"]=session->getSwgxrFine();out["time_left"]=session->getSwgxrTimeLeft();out["answer_given"]=session->getSwgxrAnswerGiven();out["answer_pending"]=phase==9 && !session->getSwgxrAnswerGiven();return out;}
 static Json state(CreatureObject* c){int status=c->getFactionStatus(),future=c->getFutureFactionStatus();uint64 deadline=0;auto text=c->getPlayerObject()->getScreenPlayData("swgxr_gcw","transition_deadline");if(!text.isEmpty())try{deadline=std::stoull(text.toCharArray());}catch(...){}return {{"faction",faction(c)},{"status",status},{"status_name",c->isNeutral()?"neutral":status==0?"on_leave":"combatant"},{"pve_only",true},{"changing",future>=0},{"pending_status",future},{"cooldown_remaining_ms",future>=0 && deadline>now()?deadline-now():0},{"standings",{{"imperial",standing(c,"imperial")},{"rebel",standing(c,"rebel")}}},{"recruiters",Json::array()},{"scan",scan(c)}};}
 static void describe(CreatureObject* c,SceneObject* npc,Json& view){std::string f=faction(npc->asCreatureObject());view["faction"]=f;view["status"]=c->getFactionStatus();view["can_join"]=c->isNeutral() && c->getFutureFactionStatus()<0;view["can_toggle"]=canToggle(c,npc);view["can_salute"]=canToggle(c,npc) && c->isInRange(npc,3) && CollisionManager::checkLineOfSight(npc,c);view["reason"]=faction(c)!=f && !c->isNeutral()?"A member of the opposing faction cannot enlist or purchase rewards.":c->getFutureFactionStatus()>=0?"A faction status change is already pending.":"";std::string greeting=c->isNeutral()?(f=="imperial"?"s_414":"s_566"):faction(c)!=f?(f=="imperial"?"s_308":"s_464"):c->getFactionStatus()==0?(f=="imperial"?"s_80":"s_448"):(f=="imperial"?"s_310":"s_466");view["recruiter_text"]="@conversation/faction_recruiter_"+f+":"+greeting;auto fm=FactionManager::instance();int rank=c->getFactionRank(),next=rank+1;bool highest=fm->isHighestRank(rank);int promotion=highest?0:fm->getRankCost(next);view["rank"]=rank;view["rank_name"]="@faction_recruiter:"+str(fm->getRankName(rank));view["next_rank"]=highest?-1:next;view["next_rank_name"]=highest?"":"@faction_recruiter:"+str(fm->getRankName(next));view["promotion_cost_faction_points"]=promotion;std::string why=faction(c)!=f?"Faction membership required.":c->getFactionStatus()==0?"Return to combatant duty first.":c->getFutureFactionStatus()>=0?"A faction status change is pending.":highest?"Highest original faction rank reached.":standing(c,f)<promotion+200?"Insufficient faction points for promotion and 200 point reserve.":"";view["can_promote"]=why.empty();view["promotion_reason"]=why;view["rewards"]=Json::array();for(auto row:catalog()["rewards"]){if(row.value("faction",std::string())!=f)continue;auto category=row.value("category",std::string());if(category!="weaponsArmor" && category!="uniforms" && category!="furniture")continue;int price=cost(c,f,row.at("key").get<std::string>());row["cost_faction_points"]=price;std::string reason=c->getFutureFactionStatus()>=0?"A faction status change is pending.":faction(c)!=f?"Faction membership required.":c->getFactionStatus()==0?"Return to combatant duty to requisition rewards.":price<0?"Original reward unavailable.":standing(c,f)<price+200?"Insufficient faction points; retain the original 200 point standing reserve.":c->getInventory()==nullptr || c->getInventory()->isContainerFullRecursive()?"Inventory is full.":"";row["eligible"]=reason.empty();row["reason"]=reason;view["rewards"].push_back(row);}}
 static Json mutate(CreatureObject* c,SceneObject* npc,const Json& r){std::string action=r.at("action").get<std::string>();if(!c->isOnline() || !c->getPlayerObject() || c->getPlayerObject()->isOnLoadScreen())throw std::runtime_error("native_ready_player_required");if(action=="contraband_answer"){auto session=c->getActiveSession(SessionFacadeType::CONTRABANDSCAN).castTo<ContrabandScanSession*>();if(!session || r.at("scan_id").get<std::string>()!=std::to_string(session->getSwgxrScanID()) || session->getSwgxrPhase()!=9 || session->getSwgxrAnswerGiven())throw std::runtime_error("native_pending_contraband_fine_required");session->setAcceptFineAnswer(r.at("accept").get<bool>());c->getPlayerObject()->closeSuiWindowType(SuiWindowType::CONTRABAND_SCAN_FINE);return {{"accepted",r["accept"]},{"pending_native_scan",true}};}
  validate(c,npc,action=="recruiter_status_toggle"?3:5);std::string f=faction(npc->asCreatureObject());
  if(action=="recruiter_join"){if(!c->isNeutral() || c->getFutureFactionStatus()>=0)throw std::runtime_error("neutral_unaffiliated_player_required");c->setFaction(npc->asCreatureObject()->getFaction());c->setFactionStatus(FactionStatus::COVERT);return {{"faction",f},{"status",1}};}
  if(action=="recruiter_status_toggle"){if(!canToggle(c,npc) || r.at("expected_status").get<int>()!=c->getFactionStatus())throw std::runtime_error("faction_status_changed_or_transition_unavailable");int status=c->getFactionStatus()==0?1:0;auto lua=DirectorManager::instance()->getLuaInstance();LuaFunction fn(lua->getLuaState(),"recruiterScreenplay","swgxrToggle",1);fn<<c;fn<<status;fn.callFunction();int delay=lua_tointeger(lua->getLuaState(),-1);lua_pop(lua->getLuaState(),1);if(delay<=0 || c->getFutureFactionStatus()!=status)throw std::runtime_error("native_faction_transition_rejected");c->getPlayerObject()->setScreenPlayData("swgxr_gcw","transition_deadline",String(std::to_string(now()+delay).c_str()));return {{"pending_status",status},{"delay_ms",delay}};}
  if(action=="recruiter_promote"){Json view;describe(c,npc,view);if(r.at("expected_rank").get<int>()!=c->getFactionRank())throw std::runtime_error("faction_rank_changed");if(!view["can_promote"].get<bool>())throw std::runtime_error(view["promotion_reason"].get<std::string>());int price=view["promotion_cost_faction_points"].get<int>(),next=view["next_rank"].get<int>();c->getPlayerObject()->decreaseFactionStanding(String(f.c_str()),price);c->setFactionRank(next);return {{"rank",next},{"faction_points_paid",price}};}
  Json view;describe(c,npc,view);for(auto& row:view["rewards"]){if(row["id"]!=r.at("reward_id"))continue;if(!row["eligible"].get<bool>())throw std::runtime_error(row["reason"].get<std::string>());int before=standing(c,f);auto lua=DirectorManager::instance()->getLuaInstance();LuaFunction fn(lua->getLuaState(),"recruiterScreenplay","awardItem",1);fn<<c;fn<<f.c_str();fn<<row.at("key").get<std::string>().c_str();fn<<c->getZone()->getGCWManager()->getGCWDiscount(c);fn.callFunction();bool valid=lua_isnumber(lua->getLuaState(),-1);int code=valid?lua_tointeger(lua->getLuaState(),-1):-1;lua_pop(lua->getLuaState(),1);if(code!=0)throw std::runtime_error("native_faction_purchase_rejected_"+std::to_string(code));return {{"reward_id",row["id"]},{"faction_points_paid",before-standing(c,f)}};}throw std::runtime_error("original_supported_faction_reward_required");
 }
};
#endif
